head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/CIRCLE/data/CIRCLE.json";  // data(type:donut, columns) 조회

scwin.CHART_CONFIG = {
    global: {
        color: { theme: "pastel" },
        padding: { top: 10, right: 10, bottom: 10, left: 10 },
        animation: { show: true, delay: 80 },
        onclick: function (data) {
            var v = (data && data.values) ? data.values : data;
            scwin.fn_click("조각 클릭됨");
        }
    },
    title: { text: "부서별 비중", position: "top" },
    legend: { show: true, position: "right", itemGap: 8 },
    tooltip: {
        format: {                                          // 포맷 함수(제목/이름/값)
            value: function (v) { return Number(v).toLocaleString() + " 건"; }
        }
    },
    extend: {
        donut: {
            innerRadius: 0.6,                              // 도넛 두께
            cornerRadius: 4,                               // 조각 모서리
            padding: 0.02,                                 // 조각 간격
            title: { text: "합계", useTotal: true },        // 가운데 제목
            label: { show: true, format: function (v) { return v + "%"; } }  // 조각 라벨
        }
    }
};

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("donut", data, chartWrap, scwin.CHART_CONFIG);
};
scwin.fn_click = function (msg) { 
	$c.win.alert(msg)
};
